using System.IdentityModel.Tokens.Jwt;
using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text;
using Microsoft.IdentityModel.Tokens;
using TaskApi;
using Xunit;

namespace TaskApi.Tests;

public sealed class AcceptanceTests
{
    [Fact] public async Task Health_is_public_and_stable() { using var api = new ApiFixture(); using var c = api.CreateClient(); var response = await c.GetAsync("/health"); Assert.Equal(HttpStatusCode.OK, response.StatusCode); Assert.Contains("ok", await response.Content.ReadAsStringAsync()); }
    [Fact] public async Task Unknown_route_remains_404() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.NotFound, (await c.GetAsync("/missing-route")).StatusCode); }
    [Fact] public async Task Valid_login_issues_signed_scoped_expiring_jwt()
    {
        using var api = new ApiFixture(); using var c = await api.Login(); var token = c.DefaultRequestHeaders.Authorization!.Parameter!;
        var handler = new JwtSecurityTokenHandler(); handler.MapInboundClaims = false;
        var principal = handler.ValidateToken(token, new TokenValidationParameters { ValidateIssuerSigningKey = true, IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(ApiFixture.Key)), ValidateIssuer = true, ValidIssuer = ApiFixture.Issuer, ValidateAudience = true, ValidAudience = ApiFixture.Audience, ValidateLifetime = true, ClockSkew = TimeSpan.Zero }, out var validated);
        Assert.Equal("alice@example.test", principal.FindFirst("sub")?.Value); var jwt = Assert.IsType<JwtSecurityToken>(validated); Assert.Equal("HS256", jwt.Header.Alg); Assert.InRange(jwt.ValidTo - DateTime.UtcNow, TimeSpan.FromMinutes(1), TimeSpan.FromMinutes(16));
    }
    [Fact] public async Task Wrong_password_is_rejected() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.Unauthorized, (await c.PostAsJsonAsync("/api/auth/login", new LoginRequest("alice@example.test", "wrong"))).StatusCode); }
    [Fact] public async Task Unknown_account_is_rejected() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.Unauthorized, (await c.PostAsJsonAsync("/api/auth/login", new LoginRequest("nobody@example.test", "Alice!234"))).StatusCode); }
    [Fact] public async Task Empty_credentials_are_invalid() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/api/auth/login", new LoginRequest("", ""))).StatusCode); }
    [Fact] public async Task Anonymous_read_is_rejected() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/tasks")).StatusCode); }
    [Fact] public async Task Anonymous_create_is_rejected() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.Unauthorized, (await c.PostAsJsonAsync("/api/tasks", new TaskInput("x"))).StatusCode); }
    [Fact] public async Task Anonymous_update_is_rejected() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.Unauthorized, (await c.PutAsJsonAsync($"/api/tasks/{Guid.NewGuid()}", new TaskInput("x"))).StatusCode); }
    [Fact] public async Task Anonymous_delete_is_rejected() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.Unauthorized, (await c.DeleteAsync($"/api/tasks/{Guid.NewGuid()}")).StatusCode); }
    [Fact] public async Task Malformed_token_is_rejected() { using var api = new ApiFixture(); using var c = api.CreateClient(); c.DefaultRequestHeaders.Authorization = new("Bearer", "invalid.jwt"); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/tasks")).StatusCode); }
    [Fact] public async Task Expired_token_is_rejected() { using var api = new ApiFixture(); using var c = api.CreateClient(); c.DefaultRequestHeaders.Authorization = new("Bearer", ApiFixture.SignedToken(DateTime.UtcNow.AddMinutes(-10))); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/tasks")).StatusCode); }
    [Fact] public async Task Token_with_wrong_signature_is_rejected() { using var api = new ApiFixture(); using var c = api.CreateClient(); c.DefaultRequestHeaders.Authorization = new("Bearer", ApiFixture.SignedToken(DateTime.UtcNow.AddMinutes(10), new string('x', 64))); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/tasks")).StatusCode); }
    [Fact] public async Task Token_with_wrong_issuer_is_rejected() { using var api = new ApiFixture(); using var c = api.CreateClient(); c.DefaultRequestHeaders.Authorization = new("Bearer", ApiFixture.SignedToken(DateTime.UtcNow.AddMinutes(10), issuer: "wrong-issuer")); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/tasks")).StatusCode); }
    [Fact] public async Task Token_with_wrong_audience_is_rejected() { using var api = new ApiFixture(); using var c = api.CreateClient(); c.DefaultRequestHeaders.Authorization = new("Bearer", ApiFixture.SignedToken(DateTime.UtcNow.AddMinutes(10), audience: "wrong-audience")); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/tasks")).StatusCode); }
    [Fact] public async Task New_user_starts_with_empty_collection() { using var api = new ApiFixture(); using var c = await api.Login(); Assert.Empty((await c.GetFromJsonAsync<TaskDto[]>("/api/tasks"))!); }
    [Fact] public async Task Create_normalizes_title_and_returns_location() { using var api = new ApiFixture(); using var c = await api.Login(); var r = await c.PostAsJsonAsync("/api/tasks", new TaskInput("  Ship API  ")); Assert.Equal(HttpStatusCode.Created, r.StatusCode); var task = (await r.Content.ReadFromJsonAsync<TaskDto>())!; Assert.NotEqual(Guid.Empty, task.Id); Assert.Equal("Ship API", task.Title); Assert.False(task.Completed); Assert.Equal($"/api/tasks/{task.Id}", r.Headers.Location?.OriginalString); Assert.Single((await c.GetFromJsonAsync<TaskDto[]>("/api/tasks"))!); }
    [Fact] public async Task Blank_title_is_invalid() { using var api = new ApiFixture(); using var c = await api.Login(); Assert.Equal(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/api/tasks", new TaskInput("  "))).StatusCode); Assert.Empty((await c.GetFromJsonAsync<TaskDto[]>("/api/tasks"))!); }
    [Fact] public async Task Overlong_title_is_invalid() { using var api = new ApiFixture(); using var c = await api.Login(); Assert.Equal(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/api/tasks", new TaskInput(new string('a', 121)))).StatusCode); }
    [Fact] public async Task Update_persists_title_and_completion() { using var api = new ApiFixture(); using var c = await api.Login(); var task = await ApiFixture.Create(c); var r = await c.PutAsJsonAsync($"/api/tasks/{task.Id}", new TaskInput("  Done  ", true)); Assert.Equal(HttpStatusCode.OK, r.StatusCode); Assert.Equal(task with { Title = "Done", Completed = true }, await r.Content.ReadFromJsonAsync<TaskDto>()); Assert.Equal("Done", (await c.GetFromJsonAsync<TaskDto[]>("/api/tasks"))!.Single().Title); }
    [Fact] public async Task Invalid_update_preserves_original() { using var api = new ApiFixture(); using var c = await api.Login(); var task = await ApiFixture.Create(c); Assert.Equal(HttpStatusCode.BadRequest, (await c.PutAsJsonAsync($"/api/tasks/{task.Id}", new TaskInput(" ", true))).StatusCode); Assert.Equal(task, (await c.GetFromJsonAsync<TaskDto[]>("/api/tasks"))!.Single()); }
    [Fact] public async Task Unknown_task_update_returns_404() { using var api = new ApiFixture(); using var c = await api.Login(); Assert.Equal(HttpStatusCode.NotFound, (await c.PutAsJsonAsync($"/api/tasks/{Guid.NewGuid()}", new TaskInput("x"))).StatusCode); }
    [Fact] public async Task Delete_removes_task_and_second_delete_returns_404() { using var api = new ApiFixture(); using var c = await api.Login(); var task = await ApiFixture.Create(c); Assert.Equal(HttpStatusCode.NoContent, (await c.DeleteAsync($"/api/tasks/{task.Id}")).StatusCode); Assert.Empty((await c.GetFromJsonAsync<TaskDto[]>("/api/tasks"))!); Assert.Equal(HttpStatusCode.NotFound, (await c.DeleteAsync($"/api/tasks/{task.Id}")).StatusCode); }
    [Fact] public async Task Completion_filter_selects_exact_subset() { using var api = new ApiFixture(); using var c = await api.Login(); var first = await ApiFixture.Create(c, "Pending"); var second = await ApiFixture.Create(c, "Done"); await c.PutAsJsonAsync($"/api/tasks/{second.Id}", new TaskInput("Done", true)); Assert.Equal([first.Id], (await c.GetFromJsonAsync<TaskDto[]>("/api/tasks?completed=false"))!.Select(t => t.Id)); Assert.Equal([second.Id], (await c.GetFromJsonAsync<TaskDto[]>("/api/tasks?completed=true"))!.Select(t => t.Id)); }
    [Fact] public async Task Another_user_cannot_list_modify_or_delete_private_task() { using var api = new ApiFixture(); using var alice = await api.Login(); var task = await ApiFixture.Create(alice); using var bob = await api.Login("bob@example.test", "Bob!234"); Assert.Empty((await bob.GetFromJsonAsync<TaskDto[]>("/api/tasks"))!); Assert.Equal(HttpStatusCode.NotFound, (await bob.PutAsJsonAsync($"/api/tasks/{task.Id}", new TaskInput("stolen"))).StatusCode); Assert.Equal(HttpStatusCode.NotFound, (await bob.DeleteAsync($"/api/tasks/{task.Id}")).StatusCode); Assert.Equal(task, (await alice.GetFromJsonAsync<TaskDto[]>("/api/tasks"))!.Single()); }
}
